	}
	if control != `"\u0085"` {
		t.Fatalf("U+0085 encoding = %s, want \"\\u0085\"", control)
	}
	if literal != `"\\u0085"` {
		t.Fatalf("literal text encoding = %s, want \"\\\\u0085\"", literal)
	}
	if got := decodeSegment(t, literal); got != `\u0085` {
